/* IEEE double, round-to-nearest-even (what exactinit() computes). */
constexpr double epsilon = 0x1.0p-53;
constexpr double splitter = 0x1.0p27 + 1.0;
constexpr double resulterrbound = (3.0 + 8.0 * epsilon) * epsilon;
constexpr double ccwerrboundA = (3.0 + 16.0 * epsilon) * epsilon;
constexpr double ccwerrboundB = (2.0 + 12.0 * epsilon) * epsilon;
constexpr double ccwerrboundC = (9.0 + 64.0 * epsilon) * epsilon * epsilon;
constexpr double o3derrboundA = (7.0 + 56.0 * epsilon) * epsilon;
constexpr double o3derrboundB = (3.0 + 28.0 * epsilon) * epsilon;
constexpr double o3derrboundC = (26.0 + 288.0 * epsilon) * epsilon * epsilon;
constexpr double iccerrboundA = (10.0 + 96.0 * epsilon) * epsilon;
constexpr double iccerrboundB = (4.0 + 48.0 * epsilon) * epsilon;
constexpr double iccerrboundC = (44.0 + 576.0 * epsilon) * epsilon * epsilon;
constexpr double isperrboundA = (16.0 + 224.0 * epsilon) * epsilon;
constexpr double isperrboundB = (5.0 + 72.0 * epsilon) * epsilon;
constexpr double isperrboundC = (71.0 + 1408.0 * epsilon) * epsilon * epsilon;

inline double Absolute(double a)
{
  return a >= 0.0 ? a : -a;
}

inline void Fast_Two_Sum_Tail(double a, double b, double x, double &y)
{
  double bvirt;
  bvirt = x - a;
  y = b - bvirt;
}

inline void Fast_Two_Sum(double a, double b, double &x, double &y)
{
  x =  (a + b);
  Fast_Two_Sum_Tail(a, b, x, y);
}

inline void Fast_Two_Diff_Tail(double a, double b, double x, double &y)
{
  double bvirt;
  bvirt = a - x;
  y = bvirt - b;
}

inline void Fast_Two_Diff(double a, double b, double &x, double &y)
{
  x =  (a - b);
  Fast_Two_Diff_Tail(a, b, x, y);
}

inline void Two_Sum_Tail(double a, double b, double x, double &y)
{
  double bvirt, avirt, bround, around;
  bvirt =  (x - a);
  avirt = x - bvirt;
  bround = b - bvirt;
  around = a - avirt;
  y = around + bround;
}

inline void Two_Sum(double a, double b, double &x, double &y)
{
  x =  (a + b);
  Two_Sum_Tail(a, b, x, y);
}

inline void Two_Diff_Tail(double a, double b, double x, double &y)
{
  double bvirt, avirt, bround, around;
  bvirt =  (a - x);
  avirt = x + bvirt;
  bround = bvirt - b;
  around = a - avirt;
  y = around + bround;
}

inline void Two_Diff(double a, double b, double &x, double &y)
{
  x =  (a - b);
  Two_Diff_Tail(a, b, x, y);
}

inline void Split(double a, double &ahi, double &alo)
{
  double c, abig;
  c =  (splitter * a);
  abig =  (c - a);
  ahi = c - abig;
  alo = a - ahi;
}

inline void Two_Product_Tail(double a, double b, double x, double &y)
{
  double ahi, alo, bhi, blo, err1, err2, err3;
  Split(a, ahi, alo);
  Split(b, bhi, blo);
  err1 = x - (ahi * bhi);
  err2 = err1 - (alo * bhi);
  err3 = err2 - (ahi * blo);
  y = (alo * blo) - err3;
}

inline void Two_Product(double a, double b, double &x, double &y)
{
  x =  (a * b);
  Two_Product_Tail(a, b, x, y);
}

inline void Two_Product_Presplit(double a, double b, double bhi, double blo, double &x, double &y)
{
  double ahi, alo, err1, err2, err3;
  x =  (a * b);
  Split(a, ahi, alo);
  err1 = x - (ahi * bhi);
  err2 = err1 - (alo * bhi);
  err3 = err2 - (ahi * blo);
  y = (alo * blo) - err3;
}

inline void Two_Product_2Presplit(double a, double ahi, double alo, double b, double bhi, double blo, double &x, double &y)
{
  double err1, err2, err3;
  x =  (a * b);
  err1 = x - (ahi * bhi);
  err2 = err1 - (alo * bhi);
  err3 = err2 - (ahi * blo);
  y = (alo * blo) - err3;
}

inline void Square_Tail(double a, double x, double &y)
{
  double ahi, alo, err1, err3;
  Split(a, ahi, alo);
  err1 = x - (ahi * ahi);
  err3 = err1 - ((ahi + ahi) * alo);
  y = (alo * alo) - err3;
}

inline void Square(double a, double &x, double &y)
{
  x =  (a * a);
  Square_Tail(a, x, y);
}

inline void Two_One_Sum(double a1, double a0, double b, double &x2, double &x1, double &x0)
{
  double _i;
  Two_Sum(a0, b , _i, x0);
  Two_Sum(a1, _i, x2, x1);
}

inline void Two_One_Diff(double a1, double a0, double b, double &x2, double &x1, double &x0)
{
  double _i;
  Two_Diff(a0, b , _i, x0);
  Two_Sum( a1, _i, x2, x1);
}

inline void Two_Two_Sum(double a1, double a0, double b1, double b0, double &x3, double &x2, double &x1, double &x0)
{
  double _j, _0;
  Two_One_Sum(a1, a0, b0, _j, _0, x0);
  Two_One_Sum(_j, _0, b1, x3, x2, x1);
}

inline void Two_Two_Diff(double a1, double a0, double b1, double b0, double &x3, double &x2, double &x1, double &x0)
{
  double _j, _0;
  Two_One_Diff(a1, a0, b0, _j, _0, x0);
  Two_One_Diff(_j, _0, b1, x3, x2, x1);
}

inline void Four_One_Sum(double a3, double a2, double a1, double a0, double b, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _j;
  Two_One_Sum(a1, a0, b , _j, x1, x0);
  Two_One_Sum(a3, a2, _j, x4, x3, x2);
}

inline void Four_Two_Sum(double a3, double a2, double a1, double a0, double b1, double b0, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _k, _0, _1, _2;
  Four_One_Sum(a3, a2, a1, a0, b0, _k, _2, _1, _0, x0);
  Four_One_Sum(_k, _2, _1, _0, b1, x5, x4, x3, x2, x1);
}

inline void Four_Four_Sum(double a3, double a2, double a1, double a0, double b4, double b3, double b1, double b0, double &x7, double &x6, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _l, _0, _1, _2;
  Four_Two_Sum(a3, a2, a1, a0, b1, b0, _l, _2, _1, _0, x1, x0);
  Four_Two_Sum(_l, _2, _1, _0, b4, b3, x7, x6, x5, x4, x3, x2);
}

inline void Eight_One_Sum(double a7, double a6, double a5, double a4, double a3, double a2, double a1, double a0, double b, double &x8, double &x7, double &x6, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _j;
  Four_One_Sum(a3, a2, a1, a0, b , _j, x3, x2, x1, x0);
  Four_One_Sum(a7, a6, a5, a4, _j, x8, x7, x6, x5, x4);
}

inline void Eight_Two_Sum(double a7, double a6, double a5, double a4, double a3, double a2, double a1, double a0, double b1, double b0, double &x9, double &x8, double &x7, double &x6, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _k, _0, _1, _2, _3, _4, _5, _6;
  Eight_One_Sum(a7, a6, a5, a4, a3, a2, a1, a0, b0, _k, _6, _5, _4, _3, _2,                  _1, _0, x0);
  Eight_One_Sum(_k, _6, _5, _4, _3, _2, _1, _0, b1, x9, x8, x7, x6, x5, x4,                  x3, x2, x1);
}

inline void Eight_Four_Sum(double a7, double a6, double a5, double a4, double a3, double a2, double a1, double a0, double b4, double b3, double b1, double b0, double &x11, double &x10, double &x9, double &x8, double &x7, double &x6, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _l, _0, _1, _2, _3, _4, _5, _6;
  Eight_Two_Sum(a7, a6, a5, a4, a3, a2, a1, a0, b1, b0, _l, _6, _5, _4, _3,                  _2, _1, _0, x1, x0);
  Eight_Two_Sum(_l, _6, _5, _4, _3, _2, _1, _0, b4, b3, x11, x10, x9, x8,                  x7, x6, x5, x4, x3, x2);
}

inline void Two_One_Product(double a1, double a0, double b, double &x3, double &x2, double &x1, double &x0)
{
  double bhi, blo, _i, _j, _k, _0;
  Split(b, bhi, blo);
  Two_Product_Presplit(a0, b, bhi, blo, _i, x0);
  Two_Product_Presplit(a1, b, bhi, blo, _j, _0);
  Two_Sum(_i, _0, _k, x1);
  Fast_Two_Sum(_j, _k, x3, x2);
}

inline void Four_One_Product(double a3, double a2, double a1, double a0, double b, double &x7, double &x6, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double bhi, blo, _i, _j, _k, _0;
  Split(b, bhi, blo);
  Two_Product_Presplit(a0, b, bhi, blo, _i, x0);
  Two_Product_Presplit(a1, b, bhi, blo, _j, _0);
  Two_Sum(_i, _0, _k, x1);
  Fast_Two_Sum(_j, _k, _i, x2);
  Two_Product_Presplit(a2, b, bhi, blo, _j, _0);
  Two_Sum(_i, _0, _k, x3);
  Fast_Two_Sum(_j, _k, _i, x4);
  Two_Product_Presplit(a3, b, bhi, blo, _j, _0);
  Two_Sum(_i, _0, _k, x5);
  Fast_Two_Sum(_j, _k, x7, x6);
}

inline void Two_Two_Product(double a1, double a0, double b1, double b0, double &x7, double &x6, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double bhi, blo, _i, _j, _k, _l, _m, _n, _0, _1, _2, a0hi, a0lo, a1hi, a1lo;
  Split(a0, a0hi, a0lo);
  Split(b0, bhi, blo);
  Two_Product_2Presplit(a0, a0hi, a0lo, b0, bhi, blo, _i, x0);
  Split(a1, a1hi, a1lo);
  Two_Product_2Presplit(a1, a1hi, a1lo, b0, bhi, blo, _j, _0);
  Two_Sum(_i, _0, _k, _1);
  Fast_Two_Sum(_j, _k, _l, _2);
  Split(b1, bhi, blo);
  Two_Product_2Presplit(a0, a0hi, a0lo, b1, bhi, blo, _i, _0);
  Two_Sum(_1, _0, _k, x1);
  Two_Sum(_2, _k, _j, _1);
  Two_Sum(_l, _j, _m, _2);
  Two_Product_2Presplit(a1, a1hi, a1lo, b1, bhi, blo, _j, _0);
  Two_Sum(_i, _0, _n, _0);
  Two_Sum(_1, _0, _i, x2);
  Two_Sum(_2, _i, _k, _1);
  Two_Sum(_m, _k, _l, _2);
  Two_Sum(_j, _n, _k, _0);
  Two_Sum(_1, _0, _j, x3);
  Two_Sum(_2, _j, _i, _1);
  Two_Sum(_l, _i, _m, _2);
  Two_Sum(_1, _k, _i, x4);
  Two_Sum(_2, _i, _k, x5);
  Two_Sum(_m, _k, x7, x6);
}

inline void Two_Square(double a1, double a0, double &x5, double &x4, double &x3, double &x2, double &x1, double &x0)
{
  double _j, _k, _l, _0, _1, _2;
  Square(a0, _j, x0);
  _0 = a0 + a0;
  Two_Product(a1, _0, _k, _1);
  Two_One_Sum(_k, _1, _j, _l, _2, x1);
  Square(a1, _j, _1);
  Two_Two_Sum(_j, _1, _l, _2, x5, x4, x3, x2);
}

